CREATE OR REPLACE FUNCTION public.fn_get_classroom_by_id(p_tenant_id uuid, p_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, branch_id uuid, name character varying, display_name character varying, short_name character varying, code character varying, description text, classroom_type character varying, status character varying, age_group character varying, min_age_months integer, max_age_months integer, capacity integer, current_enrollment integer, environment character varying, photo_url text, draft_data jsonb, profile_completion_percentage integer, is_active boolean, created_at timestamp with time zone, created_by uuid, updated_at timestamp with time zone, updated_by uuid)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT cl.id, cl.tenant_id, cl.branch_id, cl.name, cl.display_name, cl.short_name,            cl.code, cl.description, cl.classroom_type, cl.status, cl.age_group,            cl.min_age_months, cl.max_age_months, cl.capacity, cl.current_enrollment,            cl.environment, cl.photo_url, cl.draft_data, cl.profile_completion_percentage,            cl.is_active, cl.created_at, cl.created_by, cl.updated_at, cl.updated_by     FROM classrooms cl     WHERE cl.id = p_id AND cl.tenant_id = p_tenant_id; END; $function$ ;
